-- =============================================================================
-- The Emaus — dane inwestycji (tabela pages, patrz db/schema.sql)
-- =============================================================================
--
-- Wygenerowane z analizy starego projektu kgd-group-deweloper:
--   src/components/templates/the-emaus/**
--   src/data/pages/inwestycja/the-emaus/**
--
-- Architektura bardzo zbliżona do już zmigrowanego krj307-2 (te same nazwy
-- komponentów: NavBar/Hero/AboutUs/Features/Apartaments/Cta/Localization/
-- Map/Gallery/PriceHistory), ale z realnymi różnicami zachowanymi 1:1:
--   - "Hero" — statyczny obraz (header-emaus.webp), NIE wideo jak w krj307-2.
--   - "NavBar" — bez telefonu (w źródle brak pola/renderowania telefonu).
--   - "Map" — w tej inwestycji to STATYCZNY OBRAZ (mapa-emaus.webp) z
--     nagłówkiem, NIE mapa Leaflet — dokładnie jak w oryginalnym Map.jsx.
--     Kotwica "UDOGODNIENIA" z NavBar prowadzi właśnie tutaj, nie do sekcji
--     "Features" (ta w źródle nie ma własnego id).
--   - "Localization" — tu ma własną listę "places" (ikony + tytuły miejsc w
--     pobliżu) obok zdjęcia z tekstem, inaczej niż krj307-2 (tam czysty tekst).
--   - "Cta" — sterowane przez "blocks" (pętla po 2 elementach z własnym
--     nagłówkiem i PDF-em, wspólny tekst/przycisk), inny kształt niż
--     "standardHeader/prospectusHeader" w krj307-2.
--   - "Gallery" — w źródle PhoneCall pobierał zdjęcia z zewnętrznego API
--     (the-emaus.pl/acp/api/content/items/gallery) zamiast mieć je
--     zahardkodowane jak krj307-2. Użyto zamiast tego 17 lokalnie
--     zbundlowanych plików (1-17.webp) już obecnych w starym repo,
--     w kolejności numerycznej (brak śladu oryginalnej kolejności z API).
--   - "Apartaments"/"PriceHistory" — fetch do zewnętrznego CMS
--     (the-emaus.pl/acp/api/...) zastąpiony 6 placeholderowymi apartamentami
--     (M1-M6, 127 m² zgodnie z opisem SEO) — do uzupełnienia w adminie.
--   - "Cta.blocks[].pdfUrl" wskazywały na pliki PDF hostowane na
--     the-emaus.pl/upload/... (zewnętrzne, nie zbundlowane) — zostawione
--     puste do uzupełnienia w adminie.
--
-- UPSERT (ON DUPLICATE KEY UPDATE) — bezpieczne przy ponownym imporcie.
--
-- Import: mysql -u UZYTKOWNIK -p NAZWA_BAZY < db/inwestycje/the-emaus.sql
-- =============================================================================

INSERT INTO pages (slug, content) VALUES
  ('/inwestycja/the-emaus', '{"slug":"/inwestycja/the-emaus","parent":null,"template":"the-emaus","title":{"value":"The Emaus | Zamieszkaj wyjątkowo","editable":true,"label":"Tytuł strony"},"updatedAt":"2026-09-07","status":"published","nav":{"label":"The Emaus","order":16},"seo":{"title":{"value":"The Emaus – apartamenty przy ul. Emaus","editable":true,"label":"Tytuł SEO"},"description":{"value":"Prestiżowa inwestycja przy ul. Emaus: apartamenty 127 m² z ogrodami i tarasami, inteligentny dom, siłownia, sauna oraz miejsca postojowe.","editable":true,"label":"Opis SEO"},"keywords":["The Emaus","apartamenty Kraków","ul. Emaus","inteligentny dom","apartamenty z ogrodem","luksusowe mieszkania Kraków"],"canonical":"https://kgd-group.pl/inwestycja/the-emaus","robots":{"index":true,"follow":true},"author":"KGD Group","ogTitle":"The Emaus – apartamenty przy ul. Emaus","ogDescription":"Prestiżowa inwestycja przy ul. Emaus: apartamenty 127 m² z ogrodami i tarasami, inteligentny dom, siłownia, sauna oraz miejsca postojowe.","ogImage":"https://kgd-group.pl/assets/images/og-image-kgd.jpg","ogType":"website","ogUrl":"https://kgd-group.pl/inwestycja/the-emaus","ogSiteName":"KGD Group","ogLocale":"pl_PL","twitterCard":"summary_large_image","twitterTitle":"The Emaus – apartamenty przy ul. Emaus","twitterDescription":"Prestiżowa inwestycja przy ul. Emaus: apartamenty 127 m² z ogrodami i tarasami, inteligentny dom, siłownia, sauna oraz miejsca postojowe.","twitterImage":"https://kgd-group.pl/assets/images/og-image-kgd.jpg","language":"pl","structuredData":[{"type":"WebPage"}]},"sections":[{"id":"navbar","component":"NavBar","type":"section","label":"Nawigacja","fields":{"menu":{"value":[{"name":"O INWESTYCJI","path":"#o_inwestycji"},{"name":"APARTAMENTY","path":"#apartamenty"},{"name":"UDOGODNIENIA","path":"#udogodnienia"},{"name":"LOKALIZACJA","path":"#lokalizacja"},{"name":"GALERIA","path":"#galeria"},{"name":"DEWELOPER","path":"/"},{"name":"KONTAKT","path":"#kontakt"}],"editable":true,"label":"Linki nawigacji"}}},{"id":"hero","component":"Hero","type":"section","label":"Hero","fields":{}},{"id":"aboutus","component":"AboutUs","type":"section","label":"O inwestycji","fields":{"header":{"value":"THE EMAUS","editable":true,"label":"Nagłówek"},"text1":{"value":"THE EMAUS to inwestycja nowoczesna, przyciągająca wzrok pod kątem wizualnym ale zapewniająca również wszystkie udogodnienia praktyczne. Wyjątkowa lokalizacja daje dostęp do wszelkich korzyści centrum miasta. Inwestycja zostanie wykonana z dbałością o najdrobniejsze szczegóły, zwracając uwagę na trendy panujące w nowym, prestiżowym budownictwie. Odważna i nowoczesna bryła budynków obfituje w naturalną zieleń, która nawiązuje do zielonej okolicy.","editable":true,"label":"Tekst 1"},"text2":{"value":"Nowoczesne osiedle znajdujące się przy ulicy Emaus będzie zapewniało udogodnienia takie jak: miejsca postojowe w garażu podziemnym, ogródki do apartamentów parterowych i tarasy do mieszkań na piętrze 1, strefę chillout, myjnię dla zwierząt, myjnię dla rowerów, siłownie, obok której będzie znajdowała się sauna do wyłącznego użytku mieszkańców. Teren zostanie ogrodzony a bezpieczeństwo będzie zapewniała brama, monitoring 24h oraz ochrona na miejscu przy wjeździe na inwestycje.","editable":true,"label":"Tekst 2"}}},{"id":"features","component":"Features","type":"section","label":"Udogodnienia (grid)","fields":{"header":{"value":"Wyjątkowe THE EMAUS","editable":true,"label":"Nagłówek"},"features":{"value":[{"title":"Bezpieczeństwo","span":"Osiedle z kontrolowanym dostępem oraz inteligentnym monitoringiem z systemem alertowania zewnętrznego","icon":"fan"},{"title":"Zieleń","span":"Otoczenie zieleni z każdej strony. Inwestycja znajduje się obok terenów zielnych a na dachach planowane są zielone tarasy.","icon":"clima"},{"title":"Inteligentny dom","span":"Zestaw systemów kompatybilnych z popularnymi integratorami, które pozwolą na automatyczne i zdalne sterowanie oraz monitorowanie domu","icon":"heating"},{"title":"Lokalizacja","span":"Ciesz się prestiżową i dobrze skomunikowaną lokalizacją w Krakowie","icon":"smarthome"}],"editable":true,"label":"Cechy"}}},{"id":"apartaments","component":"Apartaments","type":"section","label":"Apartamenty","fields":{"header":{"value":"THE EMAUS","editable":true,"label":"Nagłówek"},"disclaimer1":{"value":"W prezentowanej cenie każdego mieszkania/segmentu uwzględniono miejsce do wyłącznego korzystania, wydzielone z części wspólnej, o powierzchni 12,5 m².","editable":true,"label":"Zastrzeżenie 1"},"disclaimer2":{"value":"Klient przy zakupie ponosi 50% kosztów notarialnych i opłat sądowych, gdy zawierana jest umowa deweloperska, a 100% tych kosztów w przypadku umowy przedwstępnej i/lub umowy przenoszącej własność.","editable":true,"label":"Zastrzeżenie 2"},"apartments":{"value":[{"unit":"M1","isGarage":false,"rooms":"4","area":"127","garden":"18","pricePerM2":"-","price":"-","status":"Wolne","images":[]},{"unit":"M2","isGarage":false,"rooms":"4","area":"127","garden":"18","pricePerM2":"-","price":"-","status":"Wolne","images":[]},{"unit":"M3","isGarage":false,"rooms":"4","area":"127","garden":"18","pricePerM2":"-","price":"-","status":"Wolne","images":[]},{"unit":"M4","isGarage":false,"rooms":"4","area":"127","garden":"18","pricePerM2":"-","price":"-","status":"Wolne","images":[]},{"unit":"M5","isGarage":false,"rooms":"4","area":"127","garden":"18","pricePerM2":"-","price":"-","status":"Wolne","images":[]},{"unit":"M6","isGarage":false,"rooms":"4","area":"127","garden":"18","pricePerM2":"-","price":"-","status":"Wolne","images":[]}],"editable":true,"label":"Apartamenty (placeholder — do uzupełnienia realnymi danymi/cenami w panelu admina)"},"labels":{"value":{"colUnit":"Nr Budynku","colRooms":"Liczba pokoi","colArea":"Powierzchnia","colGarden":"Ogród/Taras","colPricePerM2":"Cena za m²","colPrice":"Cena","colStatus":"Status","colDetails":"Szczegóły","seeMore":"Zobacz","priceHistory":"Historia cen"},"editable":true,"label":"Etykiety"}}},{"id":"cta","component":"Cta","type":"section","label":"Cta","fields":{"text":{"value":"Inwestycja realizowana z wysokiej klasy materiałów - trwałość, precyzja wykonania i nowoczesne technologie.","editable":true,"label":"Tekst wspólny"},"buttonLabel":{"value":"Dowiedz się więcej","editable":true,"label":"Etykieta przycisku"},"blocks":{"value":[{"header":"STANDARD WYKOŃCZENIA","pdfUrl":""},{"header":"PROSPEKT INWESTYCYJNY","pdfUrl":""}],"editable":true,"label":"Bloki (PDF-y do uzupełnienia w adminie)"}}},{"id":"localization","component":"Localization","type":"section","label":"Lokalizacja","fields":{"header":{"value":"Lokalizacja","editable":true,"label":"Nagłówek"},"text1":{"value":"THE EMAUS to idealna inwestycja dla osób, które szukają kompromisu pomiędzy korzyściami płynącymi z mieszkania w samym sercu dużego miasta oraz w otoczeniu zieleni.","editable":true,"label":"Tekst 1"},"text2":{"value":"Z drugiej natomiast skorzystają z atutów zacisznego osiedla, położonego w sąsiedztwie rzeki Rudawy oraz terenów zieleni.","editable":true,"label":"Tekst 2"},"places":{"value":[{"icon":"lasekWolski","title":"Miejsca spacerowe"},{"icon":"kopce","title":"Kopiec Kościuszki"},{"icon":"parkDecjusza","title":"Place zabaw"},{"icon":"blonia","title":"Błonia"},{"icon":"zoo","title":"ZOO"},{"icon":"rudawa","title":"Rzeka Rudawa"}],"editable":true,"label":"Miejsca w pobliżu"}}},{"id":"map","component":"Map","type":"section","label":"Infrastruktura (mapa statyczna)","fields":{"header":{"value":"Infrastruktura i udogodnienia","editable":true,"label":"Nagłówek"}}},{"id":"gallery","component":"Gallery","type":"section","label":"Galeria","fields":{"header":{"value":"Galeria","editable":true,"label":"Nagłówek"},"gallery":{"value":[{"path":"/investments/the-emaus/gallery/vis-01.webp","altText":"Galeria 1"},{"path":"/investments/the-emaus/gallery/vis-02.webp","altText":"Galeria 2"},{"path":"/investments/the-emaus/gallery/vis-03.webp","altText":"Galeria 3"},{"path":"/investments/the-emaus/g